list_shipping_methods.code:
final response = await client.shippingMethods
    .listShippingMethods(queryParams: {'limit': 20});
final shippingMethods = (response.map as Map)['shipping_methods'] as List;
for (final shippingMethod in shippingMethods) {
  print('${(shippingMethod as Map)['id']} ${shippingMethod['name']}');
}

count_shipping_methods.code:
final response = await client.shippingMethods.countShippingMethods();
final shippingMethods = (response.map as Map)['shipping_methods'] as Map;
print(shippingMethods['count']);

create_shipping_method.code:
final response = await client.shippingMethods.createShippingMethod({
  'shipping_method': {'name': 'Express Post'},
});
final shippingMethod = (response.map as Map)['shipping_method'] as Map;
print(shippingMethod['id']);

